x = 5
y = 10
if x > y:
    print('x is greater')
else:
    print('y is greater')

x = 5
y = 5
if x >= y:
    print('x is greater or equal')
elif x < y:
    print('x is lesser')

x = 10
y = 8
if x < y:
    if x > 5:
        print('Inside Nested If')
else:
    print('Outside Nested If')

x = True
y = False
if x or y:
    if x and not y:
        print('Case 1')
    else:
        print('Case 2')
else:
    print('Case 3')

a, b, c = 5, 10, 15
if a < b:
    if b < c:
        print('ABC')
    elif a < c:
        print('ACB')
    else:
        print('CBA')
else:
    print('BAC')
